-- GenDB engine variant Q21-conjunct_permutation: template q21.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  s_name,
  COUNT(*) AS numwait
FROM supplier, lineitem AS l1, orders, nation
WHERE
  n_name = $1
  AND s_nationkey = n_nationkey
  AND NOT EXISTS(
    SELECT
      *
    FROM lineitem AS l3
    WHERE
      l3.l_receiptdate > l3.l_commitdate
      AND l3.l_suppkey <> l1.l_suppkey
      AND l3.l_orderkey = l1.l_orderkey
  )
  AND EXISTS(
    SELECT
      *
    FROM lineitem AS l2
    WHERE
      l2.l_suppkey <> l1.l_suppkey AND l2.l_orderkey = l1.l_orderkey
  )
  AND l1.l_receiptdate > l1.l_commitdate
  AND o_orderstatus = 'F'
  AND o_orderkey = l1.l_orderkey
  AND s_suppkey = l1.l_suppkey
GROUP BY
  s_name
ORDER BY
  numwait DESC,
  s_name
LIMIT 100
